L=open(sys.argv[1]+'/bron.txt').read().split('\n')
def l(n): return L[n-1].strip()
def cut(n,m): t=l(n); i=t.find(m); return t[:i].strip() if i>=0 else t
def after(n,m): t=l(n); i=t.find(m); return t[i+len(m):].strip() if i>=0 else t
def mid(n,a,b): return cut(n,b) if not a else after(n,a)[: (after(n,a).find(b) if b and after(n,a).find(b)>=0 else None)].strip()
