txt='\n'.join(P)
txt=re.sub(r'\s*\[(?:[A-ZÁ-Ž][^\[\]]*?\d{4}[a-z]?(?:,\s*)?)+\]','',txt)
txt='\n'.join(x if x.startswith('### ') else re.sub(r'(?<=[a-z)])(\d{1,2})(?=[\s,.])','',x) for x in txt.split('\n'))
txt=re.sub(r'\b(RO|IC)(\d)(-\d)?\s?\b',lambda m:('research objective ' if m.group(1)=='RO' else 'criterion ')+m.group(2)+(m.group(3).replace('-',' point ') if m.group(3) else '')+' ',txt)
