txt=re.sub(r'\bSEDs\b','S E Ds',txt); txt=re.sub(r'\bSED\b','S E D',txt); txt=re.sub(r'\bMSR\b','M S R',txt); txt=re.sub(r'\bGDPR\b','G D P R',txt); txt=re.sub(r'\bTiB\b','tebibytes',txt)
txt=re.sub(r'\s*\[\.+\]','',txt); txt=re.sub(r'\[([a-z][^\]]*)\]',r'\1',txt); txt=clean(txt)
